import Link from 'next/link';
import type { EvidenceItem } from '@/lib/types';

/** Shows only fields returned by the evidence retrieval layer; nothing here is generated by the UI. */
export function EvidenceCard({ item }: { item: EvidenceItem }) {
  return (
    <article className="card evidence" aria-label={`Evidence ${item.rank}`}>
      <div className="row spread">
        <h3>[{item.rank}] <Link href={`/papers/${item.paperId}`}>{item.paperTitle}</Link></h3>
        <span className="badge ok" title="Cosine similarity between the question and this passage">relevance {item.relevanceScore.toFixed(3)}</span>
      </div>
      <p className="small muted">
        {item.authors.length > 0 && <>{item.authors.join(', ')} · </>}
        Section: {item.section ?? 'not detected'} · Page: {item.pageNumber ?? 'n/a'}
      </p>
      <blockquote className="snippet" style={{ margin: 0 }}>{item.snippet}</blockquote>
      <p style={{ marginTop: '.6rem', marginBottom: 0 }}><Link className="btn secondary sm" href={`/papers/${item.paperId}`}>Open source paper</Link></p>
    </article>
  );
}
